import java.time.Duration;
import java.util.*;
import java.util.function.*;

import io.github.resilience4j.circuitbreaker.*;
import io.github.resilience4j.retry.*;

public class Main {
    public static void main(String[] args) {
        KlienGudangTangguh klien = new KlienGudangTangguh(new GudangPalsu("400"));
        System.out.println(klien.stok("barang-aneh"));
        System.out.println("Log: " + klien.log());
        System.out.println("Panggilan gagal tercatat sirkuit: " + klien.cb.getMetrics().getNumberOfFailedCalls());
    }
}

class GudangPalsu {
    private final Deque<String> jadwal;
    int panggilan;

    GudangPalsu(String... jadwal) {
        this.jadwal = new ArrayDeque<>(Arrays.asList(jadwal));
    }

    int cekStok(String barang) {
        panggilan++;
        String hasil = jadwal.isEmpty() ? "ok" : jadwal.poll();
        if (hasil.equals("timeout")) {
            throw new IllegalStateException("timeout ke gudang");
        }
        if (hasil.equals("400")) {
            throw new IllegalArgumentException("barang tidak dikenal: " + barang);
        }
        return 7;
    }
}

class KlienGudangTangguh {
    private final GudangPalsu gudang;
    private final Map<String, Integer> cache = new HashMap<>();
    private final List<String> log = new ArrayList<>();
    final Retry retry;
    final CircuitBreaker cb;

    KlienGudangTangguh(GudangPalsu gudang) {
        this.gudang = gudang;
        RetryConfig rc = RetryConfig.custom()
                .maxAttempts(3)
                .waitDuration(Duration.ofMillis(10))
                .ignoreExceptions(IllegalArgumentException.class)
                .build();
        CircuitBreakerConfig cc = CircuitBreakerConfig.custom()
                .slidingWindowSize(4)
                .minimumNumberOfCalls(4)
                .failureRateThreshold(50)
                .waitDurationInOpenState(Duration.ofSeconds(30))
                .ignoreExceptions(IllegalArgumentException.class)
                .build();
        retry = Retry.of("gudang", rc);
        cb = CircuitBreaker.of("gudang", cc);
        retry.getEventPublisher().onRetry(e -> log.add("ulang " + e.getNumberOfRetryAttempts()));
        cb.getEventPublisher().onStateTransition(e -> log.add("sirkuit " + e.getStateTransition().getToState()));
    }

    String stok(String barang) {
        Supplier<Integer> tangguh = Retry.decorateSupplier(retry,
                CircuitBreaker.decorateSupplier(cb, () -> gudang.cekStok(barang)));
        try {
            int n = tangguh.get();
            cache.put(barang, n);
            return barang + ": " + n;
        } catch (IllegalArgumentException e) {
            return barang + ": ditolak (" + e.getMessage() + ")";
        } catch (RuntimeException e) {
            Integer n = cache.get(barang);
            return n == null ? barang + ": tidak tersedia" : barang + ": " + n + " (data terakhir)";
        }
    }

    List<String> log() {
        return log;
    }
}

